if (msg.payload && (msg.payload.hasMedia || msg.payload.type === 'image' || msg.payload.type === 'document')) {
  msg.fromPhone = msg.payload.from ? msg.payload.from.replace('@c.us', '') : '';
  return msg;
}
return null;

const data = msg.payload.extracted_data || {};
let reply = '📄 Documento (' + (data.document_type || 'ID').toUpperCase() + ') processado!\n';
if (data.full_name) reply += '👤 Nome: ' + data.full_name + '\n';
if (data.document_number) reply += '🔢 Número: ' + data.document_number + '\n';
if (data.cpf) reply += '🆔 CPF: ' + data.cpf + (data.cpf_valid ? ' (Válido)' : '') + '\n';
if (data.birth_date) reply += '🎂 Nascimento: ' + data.birth_date + '\n';
if (data.nationality) reply += '🌍 Nacionalidade: ' + data.nationality + '\n';

msg.payload = {
  to: msg.fromPhone + '@c.us',
  body: reply
};
return msg;
